mapper.select:
SELECT s.settlement_id, s.application_id, s.item_code, c.code_name AS item_name, s.expense_date, s.vendor_name, s.supply_amount, s.vat_amount, s.total_amount, s.description, s.receipt_file_name, s.status, s.reject_reason, s.created_at FROM settlement s LEFT JOIN com_code_detail c ON s.item_code = c.code_id AND c.group_id = 'EXP_ITEM'
AND s.status = #{status}
ORDER BY s.settlement_id DESC

mapper.insert:
INSERT INTO settlement (
    application_id, item_code, expense_date, vendor_name, supply_amount, vat_amount, total_amount, description, receipt_file_name, status
) VALUES (
    #{applicationId}, #{itemCode}, #{expenseDate}, #{vendorName}, #{supplyAmount}, #{vatAmount}, #{totalAmount}, #{description}, #{receiptFileName}, #{status}
)

mapper.update:
UPDATE settlement
SET status = #{status},
    reject_reason = #{rejectReason}
WHERE settlement_id = #{settlementId}
